BEGIN TRY
BEGIN TRANSACTION

    DECLARE @IdSegmentMetro         INT = (SELECT CrsId FROM DeliveryBackOffice.dbo.CatRateSegment WITH(NOLOCK) WHERE CrsShortName = 'MEH'), --14
            @IdSegmentLocal          INT = (SELECT CrsId FROM DeliveryBackOffice.dbo.CatRateSegment WITH(NOLOCK) WHERE CrsShortName = 'LOH'), --15
            @IdSegmentDepart         INT = (SELECT CrsId FROM DeliveryBackOffice.dbo.CatRateSegment WITH(NOLOCK) WHERE CrsShortName = 'DEH'), --16
            @IdSegmentRegional       INT = (SELECT CrsId FROM DeliveryBackOffice.dbo.CatRateSegment WITH(NOLOCK) WHERE CrsShortName = 'REH'), --17
            @IdSegmentForOlancho     INT = (SELECT CrsId FROM DeliveryBackOffice.dbo.CatRateSegment WITH(NOLOCK) WHERE CrsShortName = 'FOH'), --18
            @IdSegmentEspecial       INT = (SELECT CrsId FROM DeliveryBackOffice.dbo.CatRateSegment WITH(NOLOCK) WHERE CrsShortName = 'ESH'), --19
            @IdSegmentNacional       INT = (SELECT CrsId FROM DeliveryBackOffice.dbo.CatRateSegment WITH(NOLOCK) WHERE CrsShortName = 'NAH'), --21
            @IdSegmentForIslas       INT = (SELECT CrsId FROM DeliveryBackOffice.dbo.CatRateSegment WITH(NOLOCK) WHERE CrsShortName = 'FIH'), --20
            @IdSegmentForGracias     INT = (SELECT CrsId FROM DeliveryBackOffice.dbo.CatRateSegment WITH(NOLOCK) WHERE CrsShortName = 'FGH'); --33

    DECLARE @IdRate          INT = (SELECT RheId FROM DeliveryBackOffice.dbo.RateHeader WITH(NOLOCK) WHERE RheName ='Tarifario destinos express center' AND CountryId = 'HN'),
        @TypeServiceSTD  INT = (SELECT CtsId FROM DeliveryBackOffice.dbo.CatTypeService WITH(NOLOCK) WHERE CtsShortName = 'STD'), --5
        @TypeServiceCOD  INT = (SELECT CtsId FROM DeliveryBackOffice.dbo.CatTypeService WITH(NOLOCK) WHERE CtsShortName = 'COD'); --6

    DECLARE @IdPeq   INT = (SELECT AbcId FROM DeliveryBackOffice.dbo.ArticleByCustomer WITH(NOLOCK) WHERE AbcIdArticle =(SELECT ArtId FROM CatArticle WITH(NOLOCK) WHERE ArtName = 'Paquete Pequeño' and IdCountry = 'HN') AND Code = 'EXPHN076'),
        @IdMed   INT = (SELECT AbcId FROM DeliveryBackOffice.dbo.ArticleByCustomer WITH(NOLOCK) WHERE AbcIdArticle =(SELECT ArtId FROM CatArticle WITH(NOLOCK) WHERE ArtName = 'Paquete Mediano' and IdCountry = 'HN') AND Code ='EXPHN077'),
        @IdGrand INT = (SELECT AbcId FROM DeliveryBackOffice.dbo.ArticleByCustomer WITH(NOLOCK) WHERE AbcIdArticle =(SELECT ArtId FROM CatArticle WITH(NOLOCK) WHERE ArtName = 'Paquete Grande' and IdCountry = 'HN') AND Code ='EXPHN078'),
        @IdExt   INT = (SELECT AbcId FROM DeliveryBackOffice.dbo.ArticleByCustomer WITH(NOLOCK) WHERE AbcIdArticle =(SELECT ArtId FROM CatArticle WITH(NOLOCK) WHERE ArtName = 'Paquete Extra Grande' and IdCountry = 'HN') AND Code ='EXPHN079'),
        @IdSob   INT = (SELECT AbcId FROM DeliveryBackOffice.dbo.ArticleByCustomer WITH(NOLOCK) WHERE AbcIdArticle =(SELECT ArtId FROM CatArticle WITH(NOLOCK) WHERE ArtName = 'Paquete Sobredimensionado' and IdCountry = 'HN') AND Code ='EXPHN080');


    --*********************  ESTANDAR  *********************

    --INHABILITAR TARIFAS ANTIGUAS (ESTANDAR)
    UPDATE DeliveryBackOffice.dbo.RateData
    SET RowStatus = 0,
    TokenUpdated = 'SYS-TGARCIA',
    DateUpdated = GETDATE()
    WHERE RateId = @IdRate AND RowStatus = 1 AND TypeServiceId IS NOT NULL AND TypeServiceId = @TypeServiceSTD;

    --COBERTURA METRO

    --COBERTURA LOCAL

    --COBERTURA DEPARTAMENTAL

    --COBERTURA REGIONAL

    --COBERTURA NACIONAL

    --COBERTURA FORANEA OLANCHO

    --COBERTURA ESPECIAL

    --COBERTURA FORANEA ISLAS

    --COBERTURA FORANEA GRACIAS A DIOS


    --*********************  COD  *********************

    --INHABILITAR TARIFAS ANTIGUAS (COD)
    UPDATE DeliveryBackOffice.dbo.RateData
    SET RowStatus = 0,
    TokenUpdated = 'SYS-TGARCIA',
    DateUpdated = GETDATE()
    WHERE RateId = @IdRate AND RowStatus = 1 AND TypeServiceId IS NOT NULL AND TypeServiceId = @TypeServiceCOD;

    --COBERTURA METRO

    --COBERTURA LOCAL

    --COBERTURA DEPARTAMENTAL

    --COBERTURA REGIONAL

    --COBERTURA NACIONAL

    --COBERTURA FORANEA OLANCHO

    --COBERTURA ESPECIAL

    --COBERTURA FORANEA ISLAS

    --COBERTURA FORANEA GRACIAS A DIOS


    COMMIT TRANSACTION
    PRINT 'Actualización realizada correctamente.'
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0
        ROLLBACK TRANSACTION

    PRINT 'Ocurrió un error al ejecutar la actualización.'
    PRINT ERROR_MESSAGE()
END CATCH
